namespace WorldBox.Render.Text;

/// <summary>
/// Данные растрового шрифта: на каждый символ идёт байт ширины и девять байт строк,
/// старший бит — левый пиксель. Порядок глифов совпадает со строкой Chars.
/// Бинарных файлов в репозитории нет, атлас собирается при старте игры.
/// Перегенерировать: tools/gen_font.py (срез S2 заменит этот шрифт рисованным пиксель-артом).
/// </summary>
public static class PixelFontData
{
    public const int CellHeight = 9;

    public const int Baseline = 7;

    public const int MaxWidth = 8;

    public const string Chars = """0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyzАБВГДЕЁЖЗИЙКЛМНОПРСТУФХЦЧШЩЪЫЬЭЮЯабвгдеёжзийклмнопрстуфхцчшщъыьэюя !"#%&'()*+,-./:;<=>?@[\]^_{|}~°×№—""";

    public const string Packed =
        "";
}
